mapper.select:
SELECT COUNT(*)
FROM ddd_report
WHERE reporter_user_number = #{reporterUserNumber}
  AND apply_number = #{applyNumber}

mapper.update:
UPDATE ddd_user_common
SET common_report_count = IFNULL(common_report_count, 0) + 1
WHERE user_number = #{value}

UPDATE ddd_user
SET user_status = 'black'
WHERE user_number = #{value}
  AND EXISTS (
	SELECT 1
	FROM ddd_user_common
	WHERE user_number = #{value}
	  AND common_report_count >= 3
  )
